t = int(input())
for _ in range(t):
	(n, m, l) = map(int, input().split())
	lists = {}
	for i in range(m):
		a = list(map(int, input().split()))
		a = a[1:]
		for c in a:
			lists[c] = i
	s = list(map(int, input().split()))
	for i in range(l):
		s[i] = lists[s[i]]
	segs = 0
	ci = s[0]
	for j in range(1, l):
		if s[j] != ci:
			segs += 1
			ci = s[j]
	print(segs + 1)
